import{_ as n,h as o,i as e,c as l,v as t,p as s,x as i,m as p,e as h,S as c}from"./chunks/framework.Dvtg8yj2.js";const b=JSON.parse('{"title":"激活重计算","description":"","frontmatter":{"title":"激活重计算","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/activation-checkpointing.md","filePath":"llm/activation-checkpointing.md","lastUpdated":1788454257000}'),E={name:"llm/activation-checkpointing.md"};function d(m,a,A,B,u,_){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="激活重计算" tabindex="-1">激活重计算 <a class="header-anchor" href="#激活重计算" aria-label="Permalink to &quot;激活重计算&quot;">​</a></h1><div class="epigraph"><p>反向传播需要前向的中间量。与其全部存下来，不如只留若干检查点，缺的那些在反向时再算一遍。</p><footer>—— Chen et al., Training Deep Nets with Sublinear Memory Cost, 2016</footer></div><p>Transformer 预训练的显存往往不是被参数本身吃完的。一层里注意力分数、FFN 中间激活、残差与归一化的输出，都会按 batch、序列长度和隐藏维堆上去；层数一深，前向激活比参数大一个数量级是常事。Chen 等人 2016 年给出的办法后来被框架叫做 gradient checkpointing 或 activation recomputation：前向时只把少数张量标成检查点，其余立刻释放；反向走到某一段时，从最近的检查点把那段前向重放一遍，再接着算梯度。用多出来的计算换回显存，使同样的卡能放下更大的模型、更长的序列或更大的 microbatch。本篇讲这条以时间换空间的策略，以及它和流水线、序列并行叠在一起时的取舍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>反向传播对每个算子需要该算子前向的输入（有时还需要输出）。若把整张计算图画成一条长链，朴素实现会把链上几乎所有中间值留到反向结束。设一层激活体积为 \\(A\\)，共 \\(L\\) 层，仅激活就约 \\(LA\\)。参数、Adam 状态、梯度又各占一份参数量级。长上下文下 \\(A\\) 随序列线性或超线性涨，问题从「模型太大」变成「这一层的注意力中间结果太大」。</p><p>砍 batch 能减 \\(A\\)，但会伤害吞吐和流水线填充；砍序列会改变任务；把层卸到 CPU 则引入更贵的搬运。重计算走第三条路：承认反向确实需要那些值，但不承认它们必须从第一次前向一直活到现在。</p><h3 id="次线性显存的分段" tabindex="-1">次线性显存的分段 <a class="header-anchor" href="#次线性显存的分段" aria-label="Permalink to &quot;次线性显存的分段&quot;">​</a></h3><p>Chen 等人把长度为 \\(n\\) 的算子链分段。若每隔 \\(\\sqrt{n}\\) 步留一个检查点，前向额外重计算大约 \\(\\sqrt{n}\\) 量级，激活驻留也大约 \\(\\sqrt{n}\\) 段而不是 \\(n\\)。更激进的递归分段可以把内存降到对数级，重计算次数上升。深度学习框架里更常见的是按层或按块设检查点：Transformer 的每一层只保留进入该层的隐状态，层内注意力与 FFN 的大激活丢掉，反向时整层重放。<span class="marginnote">「checkpoint 一层」和「checkpoint 整个块」差的是重计算粒度。粒太粗，一次重放太长，反向峰值显存仍高；粒太细，检查点张量本身变多，节省有限，内核启动次数上升。预训练里通常以 Transformer layer 为边界，再对层内特别大的注意力张量做选择性保存。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现上，前向包装成带检查点的函数：进入时保存输入（以及必要的随机状态），函数内部的中间激活允许释放；反向时用保存的输入再跑一遍前向，然后用这次重放产生的中间值做标准的反向。随机性必须对齐：Dropout 的掩码、随机层的种子，要在检查点里一起存，否则重放与第一次前向不是同一个函数，梯度是错的。</p><p>选择性重计算比「整层全扔」更细。注意力里 softmax 的输入很大，但重算 \\(QK^\\top\\) 也贵；有的实现选择保存归一化后的张量、丢掉投影中间态，或保存 FlashAttention 的若干统计量、丢掉完整分数矩阵。Megatron 一类预训练栈把重计算分成满重计算与选择性重计算：前者层内几乎不留激活，后者留下计算代价高、体积相对可控的张量。目标是让重计算的 FLOPs 落在本来吃不满的算力空隙里，而不是把 step time 拉长一倍。</p>',11)),(e(),s(c,null,{default:i(()=>[h(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%B1%82%E8%BE%93%E5%85%A5%E4%BD%9C%E4%B8%BA%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%20--%3E%20F%5B%22%E5%89%8D%E5%90%91%EF%BC%9A%E5%A4%A7%E6%BF%80%E6%B4%BB%E7%94%A8%E5%AE%8C%E5%8D%B3%E9%87%8A%E6%94%BE%22%5D%0A%20%20F%20--%3E%20Y%5B%22%E5%B1%82%E8%BE%93%E5%87%BA%22%5D%0A%20%20Y%20--%3E%20B%5B%22%E5%8F%8D%E5%90%91%E5%88%B0%E8%BE%BE%E8%AF%A5%E5%B1%82%22%5D%0A%20%20B%20--%3E%20R%5B%22%E4%BB%8E%E6%A3%80%E6%9F%A5%E7%82%B9%E9%87%8D%E6%94%BE%E5%89%8D%E5%90%91%22%5D%0A%20%20R%20--%3E%20G%5B%22%E7%94%A8%E9%87%8D%E6%94%BE%E6%BF%80%E6%B4%BB%E7%AE%97%E6%A2%AF%E5%BA%A6%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="与流水线和序列并行一起算账" tabindex="-1">与流水线和序列并行一起算账 <a class="header-anchor" href="#与流水线和序列并行一起算账" aria-label="Permalink to &quot;与流水线和序列并行一起算账&quot;">​</a></h3><p>流水线并行已经让每张卡只持有一部分层，激活份数还随 in-flight 的 microbatch 增加。重计算作用在每张卡的本地层上，减的是「这一阶段里每个 microbatch 的激活」，两者相乘才是真实显存。序列并行 / 上下文并行把激活沿序列切开，单卡的 \\(A\\) 变小，重计算的收益也变小——该切序列还是该重计算，取决于通信墙与计算墙哪边更近。专家并行则在 All-to-All 之后产生专家侧激活，这些张量同样可以纳入检查点范围，但重放时必须还能看到当时的路由结果与容量掩码。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>重计算改变的是峰值显存，不是渐近 FLOPs 的常数项可以忽略。满层重计算大约把前向再做一次，训练 FLOPs 从「一次前向加一次反向」（反向通常约两倍前向）变成接近「两次前向加一次反向」，总计算大约增加百分之三十量级，具体取决于哪些算子被重放。若重放的是已经带宽受限的内核，墙上时间的增幅可能小于 FLOPs 增幅；若重放的是已经算力打满的 GEMM，step time 会接近按比例变慢。</p><p>数值上，重放应当与第一次前向足够接近。混合精度里，有的核在前向用某种累加精度，重放若走另一条内核路径，梯度会出现静默偏差。检查点保存的是哪一种 dtype、是否在检查点处强制一次同步，都会进入这条误差。稳定性出问题时应先确认重计算开关，再怀疑优化器。<span class="marginnote">激活重计算不是梯度检查点在「优化器状态」意义上的检查点，也不等于训练中断后的模型 checkpoint。三个词经常混用：一个管反向显存，一个管 Adam 动量是否分片，一个管磁盘上的权重快照。配置项看名字不看实现，很容易把重计算关错。</span></p><h3 id="随机状态与原地算子" tabindex="-1">随机状态与原地算子 <a class="header-anchor" href="#随机状态与原地算子" aria-label="Permalink to &quot;随机状态与原地算子&quot;">​</a></h3><p>Dropout、DropPath、以及某些数据增强在层内发生时，重放必须复现同一掩码。实现通常把 RNG 状态塞进检查点，或把掩码本身当检查点张量。原地修改（in-place ReLU、在同一块缓冲上做归一化）会破坏「输入还在」的假设，检查点包装函数必须禁止这类破坏性更新，或在进入时克隆输入。预训练框架里这类约束已经写成默认，自己改内核时容易踩回去。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>重计算换不来通信。All-Reduce、All-to-All、流水线点对点该发多少还是多少。它也换不来优化器状态：Adam 的一阶二阶矩仍按参数量活着，那是 ZeRO 的问题。当显存瓶颈已经转到优化器或通信缓冲，再加深重计算只会烧计算。</p><p>不是所有激活都值得扔。极小的偏置、已经很小的 LayerNorm 统计量，丢掉再算不回本。值得扔的是体积大、重算相对便宜、或能走已经优化过的融合核的那些。FlashAttention 把注意力中间结果留在 SRAM 里，本身就是一种更激进的「不把大激活写回 HBM」；它与层间检查点是互补关系：前者减层内峰值，后者减跨层驻留。</p><p>推理一般不需要这条技术。推理没有反向，激活只在当前步存活。不要把训练配置里的 checkpointing 原样搬到服务进程。<span class="marginnote">报告「用重计算把序列从 4k 拉到 32k」时，应同时报告 step time 增加了多少、以及重计算是满层还是选择性。只报能跑起来，会把三十个百分点的算力税藏进扩展实验里，后面的扩展律拟合会被污染。</span></p><p>Chen 等人的分析针对的是一般深度网络的链式结构。Transformer 有残差、有并行注意力-FFN、有 MoE 的动态路由，检查点边界要画在「重放仍是确定函数」的位置。路由决策若在检查点之外重新发生，专家侧的重计算会对错专家。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>激活重计算只保存部分前向张量，反向时从检查点重放，用计算换显存。</li><li>思想来自 Chen 等人 2016 年对深度网络次线性内存的分段检查点。</li><li>预训练里通常按 Transformer 层设检查点，再对注意力等大张量做选择性保存。</li><li>满层重计算大约增加三成量级的训练 FLOPs，墙上时间取决于重放内核是否算力受限。</li><li>必须保存随机状态与路由结果，否则重放不是同一个前向。</li><li>它不节省通信和优化器状态；瓶颈不在激活时不应再加深重计算。</li><li>出处：Chen et al., <em>Training Deep Nets with Sublinear Memory Cost</em>, 2016。后续预训练框架中的满重计算与选择性重计算是同一思想的工程分层。</li></ul>',14))])}const k=n(E,[["render",d]]);export{b as __pageData,k as default};
